/* @lc app=leetcode id=3799 lang=kotlin */ class Solution { fun wordSquares(words: Array<String>): List<List<String>> = words.indices.flatMap { t -> words.indices.filter { it != t }.flatMap { l -> words.indices.filter { it != t && it != l }.flatMap { r -> words.indices.filter { it != t && it != l && it != r }.filter { b -> words[t][0] == words[l][0] && words[t][3] == words[r][0] && words[b][0] == words[l][3] && words[b][3] == words[r][3] }.map { b -> listOf(words[t], words[l], words[r], words[b]) } } } }.sortedWith(compareBy({ it[0] }, { it[1] }, { it[2] }, { it[3] })) }